### Solution

```
import java.util.*;
import java.util.stream.Collectors;
public class Solution {
    public static void main(String[] args) {
        List<String> task = Arrays.asList("Celebration", "Study", "Exercise", "Relaxation", "Bathing", "Music", "Eating", "TV", "Reading", "Computer", "Sleep");
        int priority = 0;
        for(int i = 0; i < task.size(); i++) {
            if(task.get(i).equals("Celebration") || task.get(i).equals("Exercise")){
                priority++;
            }else{
                priority--;
            }
        }
        System.out.println(task.stream().sorted(Comparator.comparingInt(x -> priority)).map(x -> x.toLowerCase()).collect(Collectors.toList()));
    }
}
```

