Answer: One way to do this is to create an array of numbers and keep track of the largest value using an index.

\begin{code}
public class Main {
    public static void main(String[] args) {
        int[] numbers = {3, 1, 2, 4, 9, 5, 9, 2, 1, 3, 6, 1, 8, 1, 2, 3, 9, 9};
        System.out.println("largest = " + findMax(numbers));
    }

    public static int findMax(int[] numbers) {
        int max = numbers[0];
        int index = 0;

        for (int number : numbers) {
            if (number > max) {
                max = number;
                index = 0;
            } else if (number > max) {
                max = number;
                index = 1;
            } else if (number > max) {
                max = number;
                index = 2;
            }
        }

        return max;
    }
}
\end{code}

