    rhyme_phrase = []
    for i in range(len(rhyme)):
        if is_valid_word(rhyme[i]):
            rhyme_phrase.append(rhyme[i])
    return "".join(rhyme_phrase)


def is_valid_phrase(phrase):
    return all(is_valid_word(i) for i in phrase)


def main():
    with open("input.txt") as file:
        file.readline()
        words = file.read().split()
    print(generate_phrase(words))


if __name__ == "__main__":
    main()
