#include <iostream>
#include <vector>
#include <queue>
using namespace std;

struct TreeNode
{
    int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

int cmp(TreeNode *left, TreeNode *right)
{
    if (left->val > right->val)
        return 1;
    if (left->val < right->val)
        return -1;
    return 0;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;
    vector<TreeNode> v(n);
    for (int i = 0; i < n; ++i)
        cin >> v[i].val;

    priority_queue<TreeNode*, vector<TreeNode*>, decltype(cmp), decltype(cmp())(cmp)> q;
    for (int i = 0; i < n; ++i)
        q.push(v[i]);

    int ans = 0;
    while (!q.empty())
    {
        TreeNode *x = q.top();
        q.pop();
        ans++;

        if (x->val > 0)
            q.push(x->left);
        else
        {
            if (x->left)
                q.push(x->right);
            else
                q.push(x->left);
        }
    }

    cout << ans << endl;

    return 0;
}
