Given the head of a singly linked list, reverse the list, and return the reversed list.



Example 1:

Input: head = [1,2,3]
Output: [3,2,1]
Example 2:

Input: head = [4,5,1,2]
Output: [1,2,4,5]
Example 3:

Input: head = [1]
Output: [1]
Example 4:

Input: head = []
Output: []


Constraints:

    1. The number of nodes in the list is in the range [0, 104].
    2. -104 <= Node.val <= 104



public class Solution {
    public ListNode reverseList(ListNode head) {
        if (head == null)
            return head;
        ListNode last = head, next = head.next;
        while (next != null) {
            head.next = next;
            next = next.next;
            head = last;
            last = last.next;
        }
        head.next = null;
        return head;
    }
}

