Answer: This is what I came up with.

\begin{code}
import pylint

def generate_report(filename, lines):
    l = pylint.lint(filename)
    if l.errors == 0:
        return
    with open(filename, 'r') as f:
        lines = f.readlines()
    for line in lines:
        if line.startswith('test.py:') and line.endswith('test.py:3:1'):
            break
    print(line, end='')
    for line in lines[1:]:
        print(line, end='')
    print()

for filename in ["./test.py", "test.py"]:
    generate_report(filename, open(filename, 'r').readlines())
\end{code}

