Write a Ruby solution for this problem:

Given a sorted array of distinct integers and a target value, return the index if the target is found. If not, return the index where it would be if it were inserted in order.

You must write an algorithm with O(log n) runtime complexity.

Example:

Input: [1,3,5,6], 5
Output: 2
Explanation: 5 is found at index 2, so return 2.

Note:

You may assume that the array is non-empty and contains distinct integers.

*/

#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <algorithm>
#include <cmath>

using namespace std;

class Solution {
public:
    int searchInsert(vector<int> &nums, int target) {
        if (target < nums[0]) return 0;
        else if (target > nums[nums.size() - 1]) return nums.size() - 1;

        int start = 0;
        int end = nums.size() - 1;
        while (start <= end) {
            mid = (start + end) / 2;
            if (target == nums[mid])
                return mid;
            else if (target < nums[mid])
                start = mid + 1;
            else
                end = mid - 1;
        }
        return start;
    }
};

int main() {
    vector<int> nums{1, 3, 5, 6};
    int target = 5;
    Solution s;
    cout << s.searchInsert(nums, target) << endl;
}

