Given a list of cities, determine the closest one to the equator.
Madrid, Cairo, Beijing, Tokyo

#!/usr/bin/env python

import math

def distance(lat1, lon1, lat2, lon2):
    dlon = lon2 - lon1
    dlat = math.radians(lat2) - math.radians(lat1)
    return math.sqrt((dlon ** 2) + (dlat ** 2))

def closest_lat(lat1, lat2, lat3):
    return min(math.radians(lat1), math.radians(lat2), math.radians(lat3))

def closest_lon(lon1, lon2, lon3):
    return min(math.radians(lon1), math.radians(lon2), math.radians(lon3))

def distance_to_equator(lat1, lon1):
    return distance(lat1, lon1, closest_lat(lat1, lat2, lat3), closest_lon(lon1, lon2, lon3))

def main():
    cities = ["Madrid", "Cairo", "Beijing", "Tokyo"]

    print "Madrid: %s" % distance_to_equator(lat1, lon1)
    print "Cairo: %s" % distance_to_equator(lat1, lon1)
    print "Beijing: %s" % distance_to_equator(lat1, lon1)
    print "Tokyo: %s" % distance_to_equator(lat1, lon1)

if __name__ == "__main__":
    main()

