Find the maximum salary earned by any employee.

Negative values are considered as zero.

# Solution

## Java
```
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        System.out.println("Enter the data");
        System.out.println("\nEmployee: Salary: ");
        String[][] data = readData(sc);

        System.out.println("The maximum salary earned by an employee is " +
                Arrays.stream(data).max().mapToDouble(Double::doubleValue()).toString());
    }

    public static String[][] readData(Scanner sc) {
        int rows = sc.nextInt();
        String[][] data = new String[rows][];

        for (int i = 0; i < rows; i++) {
            data[i] = sc.nextLine().split(" ");
        }

        return data;
    }
}
